evaluation.contract:
Contract CoCoMESystem::openCashDesk(cashDeskID:Integer): Boolean {

            precondition:
          not self.CurrentStore.oclIsUndefined() and self.CurrentStore.IsOpened = true and CashDesk.allInstances()->exists(c:CashDesk| c.Id = cashDeskID and c.IsOpened = false)

            postcondition:
          result = true and self.CurrentCashDesk = CashDesk.allInstances()->any(c:CashDesk| c.Id = cashDeskID) and self.CurrentCashDesk.IsOpened = true

        }
